/** static void TrySetBattleSeminarShow(void) */
export function TrySetBattleSeminarShow(): any {
  let i: any = null;
      let dmgByMove: any = [];
      let powerOverride: any = null;
      let currMoveSaved: any = null;

      if (gBattleTypeFlags & (((1 << 0)) | ((1 << 1)) | ((1 << 25))))
          return;
      else if (GetBattlerSide(gBattlerAttacker) == (1))
          return;
      else if (gBattleMons[gBattlerAttacker].statStages[(6)] < (6))
          return;
      else if (gBattleMons[gBattlerTarget].statStages[(7)] > (6))
          return;
      else if (gCurrentMove == (237) || gCurrentMove == (311))
          return;
      else if (gBattleTypeFlags & (((1 << 17)) | ((1 << 20)) | ((1 << 21))))
          return;
      else if (gBattleMoves[gBattleMons[gBattlerAttacker].moves[gMoveSelectionCursor[gBattlerAttacker]]].power == 0)
          return;

      i = 0;
      currMoveSaved = gBattleMons[gBattlerAttacker].moves[gMoveSelectionCursor[gBattlerAttacker]];
      do
      {
          if (currMoveSaved == sVariableDmgMoves[i])
              break;
          i++;
      } while (sVariableDmgMoves[i] != TABLE_END);

      if (sVariableDmgMoves[i] != TABLE_END)
          return;

      dmgByMove[gMoveSelectionCursor[gBattlerAttacker]] = gBattleMoveDamage;
      currMoveSaved = gCurrentMove;
      for (i = 0; i < (4); i++)
      {
          gCurrentMove = gBattleMons[gBattlerAttacker].moves[i];
          powerOverride = 0;
          if (ShouldCalculateDamage(gCurrentMove,dmgByMove[i],powerOverride))
          {
              let moveResultFlags: any = null;
              let sideStatus: any = gSideStatuses[GET_BATTLER_SIDE(gBattlerTarget)];
              gBattleMoveDamage = CalculateBaseDamage(gBattleMons[gBattlerAttacker],gBattleMons[gBattlerTarget], gCurrentMove,
                                                      sideStatus, powerOverride,
                                                      0, gBattlerAttacker, gBattlerTarget);

              if (gStatuses3[gBattlerAttacker] & ((1 << 9)) && gBattleMoves[gCurrentMove].type == (13))
                  gBattleMoveDamage *= 2;
              if (gProtectStructs[gBattlerAttacker].helpingHand)
                  gBattleMoveDamage = gBattleMoveDamage * 15 / 10;

              moveResultFlags = TypeCalc(gCurrentMove, gBattlerAttacker, gBattlerTarget);
              dmgByMove[i] = gBattleMoveDamage;
              if (dmgByMove[i] == 0 && !(moveResultFlags & ((((1 << 0)) | ((1 << 3)) | ((1 << 5))))))
                  dmgByMove[i] = 1;
          }
      }

      for (i = 0; i < (4); i++)
      {
          if (i != gMoveSelectionCursor[gBattlerAttacker] && dmgByMove[i] > dmgByMove[gMoveSelectionCursor[gBattlerAttacker]])
          {
              let opponentSpecies, playerSpecies;
              let bestMoveId: any = null;

              if (gMoveSelectionCursor[gBattlerAttacker] != 0)
                  bestMoveId = 0;
              else
                  bestMoveId = 1;

              for (i = 0; i < (4); i++)
              {
                  if (i != gMoveSelectionCursor[gBattlerAttacker] && dmgByMove[i] > dmgByMove[bestMoveId])
                      bestMoveId = i;
              }

              opponentSpecies = GetMonData(gEnemyParty [gBattlerPartyIndexes[gBattlerTarget]],   MON_DATA_SPECIES, NULL);
              playerSpecies   = GetMonData(gPlayerParty[gBattlerPartyIndexes[gBattlerAttacker]], MON_DATA_SPECIES, NULL);
              TryPutBattleSeminarOnAir(opponentSpecies, playerSpecies, gMoveSelectionCursor[gBattlerAttacker], gBattleMons[gBattlerAttacker].moves, gBattleMons[gBattlerAttacker].moves[bestMoveId]);
              break;
          }
      }

      gBattleMoveDamage = dmgByMove[gMoveSelectionCursor[gBattlerAttacker]];
      gCurrentMove = currMoveSaved;
}

/** static bool8 ShouldCalculateDamage(u16 move, s32 *dmg, u16 *powerOverride) */
export function ShouldCalculateDamage(move: any, dmg: any, powerOverride: any): any {
  if (gBattleMoves[move].power == 0)
      {
          dmg = 0;
          return FALSE;
      }
      else
      {
          let i: any = 0;
          do
          {
              if (move == sVariableDmgMoves[i])
                  break;
              i++;
          } while (sVariableDmgMoves[i] != TABLE_END);

          if (sVariableDmgMoves[i] != TABLE_END)
          {
              dmg = 0;
              return FALSE;
          }
          else if (move == (149))
          {
              dmg = gBattleMons[gBattlerAttacker].level;
              dmg /= 2;
              return FALSE;
          }
          else if (move == (222))
          {
              powerOverride = 10;
              return TRUE;
          }
          else
          {
              return TRUE;
          }
      }
}

